const LEVELS = [
  {level:5,label:"ดีเยี่ยม",range:"90–100",min:90,max:100,bg:"#16a34a",text:"white",light:"#dcfce7",border:"#15803d"},
  {level:4,label:"ดีมาก",  range:"80–89", min:80,max:89, bg:"#2563eb",text:"white",light:"#dbeafe",border:"#1d4ed8"},
  {level:3,label:"ดี",     range:"70–79", min:70,max:79, bg:"#ca8a04",text:"white",light:"#fef9c3",border:"#a16207"},
  {level:2,label:"พอใช้",  range:"60–69", min:60,max:69, bg:"#ea580c",text:"white",light:"#ffedd5",border:"#c2410c"},
  {level:1,label:"ปรับปรุง",range:"< 60", min:0, max:59, bg:"#dc2626",text:"white",light:"#fee2e2",border:"#b91c1c"},
];

function getLevel(s){return LEVELS.find(l=>s>=l.min&&s<=l.max)||LEVELS[4];}
function getTotal(sc){return CRITERIA.reduce((s,c)=>s+(sc[c.id]||0),0);}
function getSectionTotal(sc,sec){return CRITERIA.filter(c=>c.section===sec).reduce((s,c)=>s+(sc[c.id]||0),0);}
function getSectionMax(sec){return CRITERIA.filter(c=>c.section===sec).reduce((s,c)=>s+c.max,0);}

function parseCSV(text){
  const lines=text.trim().split("\n");
  if(lines.length<2)return null;
  const scores={};
  DISTRICTS.forEach(d=>{scores[d]={};});
  const rows=lines.map(line=>{
    const cells=[];let cur="",inQ=false;
    for(let i=0;i<line.length;i++){
      const ch=line[i];
      if(ch==='"'){inQ=!inQ;}
      else if(ch===','&&!inQ){cells.push(cur.trim().replace(/^"|"$/g,""));cur="";}
      else cur+=ch;
    }
    cells.push(cur.trim().replace(/^"|"$/g,""));
    return cells;
  });
  let headerRowIdx=-1,districtColMap={};
  for(let r=0;r<Math.min(10,rows.length);r++){
    const row=rows[r],found={};
    row.forEach((cell,ci)=>{
      const clean=cell.replace(/\s/g,"");
      DISTRICTS.forEach(d=>{if(clean===d.replace(/\s/g,"")||cell.trim()===d)found[d]=ci;});
    });
    if(Object.keys(found).length>=5){headerRowIdx=r;districtColMap=found;break;}
  }
  if(headerRowIdx===-1)return null;
  let idCol=-1;
  for(let r=headerRowIdx+1;r<Math.min(headerRowIdx+5,rows.length);r++){
    rows[r].forEach((cell,ci)=>{if(/^\d+\.\d+/.test(cell)&&idCol===-1)idCol=ci;});
  }
  if(idCol===-1)idCol=0;
  for(let r=headerRowIdx+1;r<rows.length;r++){
    const row=rows[r];
    const rawId=(row[idCol]||"").trim();
    const crit=CRITERIA.find(c=>c.id===rawId||c.id===rawId.replace(/^F|^V/i,""));
    if(!crit)continue;
    DISTRICTS.forEach(d=>{
      const ci=districtColMap[d];if(ci===undefined)return;
      const num=parseFloat((row[ci]||"").trim().replace(/,/g,""));
      if(!isNaN(num))scores[d][crit.id]=Math.min(num,crit.max);
    });
  }
  return scores;
}

