              <span style={{display:"inline-block",marginLeft:4,padding:"1px 5px",borderRadius:99,background:selDist===d?"rgba(255,255,255,0.3)":lv2.light,color:selDist===d?"white":lv2.bg,fontSize:10,fontWeight:800}}>{t}</span>
