                    ...crit.map((c,ci)=>{const v=sc[c.id]||0;return(<tr key={c.id} style={{background:ci%2===0?"white":"#fafafa"}}><td style={{textAlign:"center",color:"#64748b",fontSize:"8.5pt"}}>{c.id}</td><td style={{fontSize:"8.5pt",lineHeight:1.45,paddingLeft:10}}>{c.label}</td><td style={{textAlign:"center"}}>{c.max}</td><td style={{textAlign:"center",fontWeight:v>0?700:400,color:v>0?"#1e293b":"#94a3b8"}}>{v}</td><td style={{textAlign:"center",color:v>0?"#2563eb":"#94a3b8"}}>{v>0?Math.round((v/c.max)*100)+"%":"–"}</td></tr>);})
