// ===== LOCAL STORAGE HELPERS =====
const LS_KEY = "rdu_scores_2569";

function loadFromStorage(){
  try{
    const raw=localStorage.getItem(LS_KEY);
    if(raw){
      const parsed=JSON.parse(raw);
      if(parsed&&typeof parsed==="object") return parsed;
    }
  }catch(e){}
  return null;
}

function saveToStorage(scores){
  try{ localStorage.setItem(LS_KEY,JSON.stringify(scores)); }catch(e){}
}

// ===== MAIN =====
export default function App(){
  const [tab,setTab]=useState("dashboard");
  // โหลดจาก localStorage ก่อน ถ้าไม่มีใช้ FALLBACK
  const [scores,setScores]=useState(()=>loadFromStorage()||FALLBACK_SCORES);
  const [syncStatus,setSyncStatus]=useState("idle");
  const [lastSync,setLastSync]=useState(null);

  // บันทึกลง localStorage ทุกครั้งที่ scores เปลี่ยน
  useEffect(()=>{saveToStorage(scores);},[scores]);

  const fetchSheetData=useCallback(async()=>{
    setSyncStatus("loading");
    try{
      const res=await fetch(CSV_URL);
      if(!res.ok)throw new Error("fetch failed");
      const text=await res.text();
      const parsed=parseCSV(text);
      if(parsed&&Object.values(parsed).some(d=>Object.keys(d).length>0)){
        setScores(parsed);setSyncStatus("ok");setLastSync(new Date());
      }else{setSyncStatus("error");}
    }catch(e){setSyncStatus("error");}
  },[]);

  useEffect(()=>{fetchSheetData();},[fetchSheetData]);
  useEffect(()=>{const id=setInterval(fetchSheetData,5*60*1000);return()=>clearInterval(id);},[fetchSheetData]);

  const handleScoreChange=useCallback((district,criteriaId,value)=>{
    setScores(prev=>{
      const next={...prev,[district]:{...prev[district],[criteriaId]:value}};
      saveToStorage(next); // บันทึกทันทีทุกครั้งที่เปลี่ยน
      return next;
    });
  },[]);

  const tabs=[
    {id:"dashboard",label:"📊 Dashboard",short:"Dashboard"},
    {id:"levels",   label:"🎯 ระดับความสำเร็จ",short:"ระดับ"},
    {id:"input",    label:"✍️ บันทึกผลคะแนน",short:"บันทึกคะแนน"},
    {id:"score",    label:"📋 คะแนนรายอำเภอ",short:"รายอำเภอ"},
    {id:"compare",  label:"📊 เปรียบเทียบ",short:"เปรียบเทียบ"},
    {id:"report",   label:"📄 รายงาน PDF",short:"PDF"},
  ];

  return(
    <>
      <style>{css}</style>
      <div className="app">
        <nav className="navbar">
          <img src={LOGO_DATA} alt="RDU Surin" className="nav-logo-img"/>
          <div className="nav-brand">
            <div className="nav-title">ระบบคะแนน RDU 2569</div>
            <div className="nav-sub">จังหวัดสุรินทร์</div>
          </div>
          <div className="nav-div"/>
          <div className="nav-tabs">
            {tabs.map(t=>(<button key={t.id} className={`nav-tab${tab===t.id?" active":""}`} onClick={()=>setTab(t.id)}>{t.label}</button>))}
          </div>
          <div className="sync-wrap">
            <div className={`sync-dot ${syncStatus}`}/>
            <span className="sync-text">{syncStatus==="loading"?"โหลด...":syncStatus==="ok"?`${lastSync?lastSync.toLocaleTimeString("th-TH",{hour:"2-digit",minute:"2-digit"}):""}` :"Fallback"}</span>
            <button className="btn-refresh" onClick={fetchSheetData}>🔄</button>
          </div>
        </nav>
        <div className="bottom-bar">
          <div className="bottom-bar-inner">
            {tabs.map(t=>(<button key={t.id} className={`btm-tab${tab===t.id?" active":""}`} onClick={()=>setTab(t.id)}><span className="btm-icon">{t.label.split(" ")[0]}</span><span style={{fontSize:9}}>{t.short}</span></button>))}
          </div>
        </div>
        {tab==="dashboard"&&<Dashboard scores={scores}/>}
        {tab==="levels"   &&<LevelDashboard scores={scores}/>}
        {tab==="input"    &&<ScoreInputTable scores={scores} onScoreChange={handleScoreChange}/>}
        {tab==="score"    &&<ScoreTable scores={scores}/>}
        {tab==="compare"  &&<CompareTable scores={scores}/>}
        {tab==="report"   &&<PDFReport scores={scores}/>}
      </div>
    </>
  );
}
